import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// ------------------------------------------
// Fused MaxPool + HardTanh kernel
// ------------------------------------------
__global__ void fused_maxpool_hardtanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int B, int C, int H, int W,
    int kernel_size, int stride,
    float min_val, float max_val)
{
    // Each thread handles one element in the output [B, C, H_out, W_out].
    // H_out = H / stride, W_out = W / stride (assuming perfect divisibility).
    int H_out = H / stride;
    int W_out = W / stride;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int c = (idx / (W_out * H_out)) % C;
    int b = idx / (W_out * H_out * C);

    int h_start = h_out * stride;
    int w_start = w_out * stride;

    float max_val_in_window = -3.4e38f; // negative large number
    for(int kh = 0; kh < kernel_size; kh++){
        for(int kw = 0; kw < kernel_size; kw++){
            int h_in = h_start + kh;
            int w_in = w_start + kw;
            float val = input[b*C*H*W + c*H*W + h_in*W + w_in];
            max_val_in_window = fmaxf(max_val_in_window, val);
        }
    }

    // Apply hardtanh
    if (max_val_in_window < min_val){
        max_val_in_window = min_val;
    } else if (max_val_in_window > max_val){
        max_val_in_window = max_val;
    }

    output[idx] = max_val_in_window;
}

torch::Tensor fused_maxpool_hardtanh_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    float min_val,
    float max_val)
{
    TORCH_CHECK(input.dim() == 4, "Input tensor must be 4D [B, C, H, W]");

    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    // Output shape
    int H_out = H / stride;
    int W_out = W / stride;

    auto out = torch::empty({B, C, H_out, W_out}, input.options());

    const int block_size = 256;
    const int num_blocks = (B*C*H_out*W_out + block_size - 1) / block_size;

    fused_maxpool_hardtanh_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, H, W,
        kernel_size, stride,
        min_val, max_val
    );

    return out;
}

// ------------------------------------------
// Fused mean over spatial dims + tanh
// ------------------------------------------
// We reduce across H, W and produce [B, C, 1, 1].
__global__ void fused_spatial_mean_tanh_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int B, int C, int H, int W)
{
    // Each thread handles one (B, C).
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C;
    if (idx >= total) return;

    int c = idx % C;
    int b = idx / C;

    // Sum over spatial
    float sum_val = 0.0f;
    for(int h = 0; h < H; h++){
        for(int w = 0; w < W; w++){
            sum_val += input[b*C*H*W + c*H*W + h*W + w];
        }
    }
    float mean_val = sum_val / (float)(H*W);

    // Apply tanh
    float out_val = tanhf(mean_val);

    // Store in [B, C, 1, 1]
    output[b*C + c] = out_val;
}

torch::Tensor fused_spatial_mean_tanh_cuda(
    torch::Tensor input)
{
    TORCH_CHECK(input.dim() == 4, "Input tensor must be 4D [B, C, H, W]");

    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto out = torch::empty({B, C, 1, 1}, input.options());

    int block_size = 256;
    int num_blocks = (B*C + block_size - 1) / block_size;

    fused_spatial_mean_tanh_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, H, W
    );

    return out;
}
"""

fused_ops_cpp_header = r"""
torch::Tensor fused_maxpool_hardtanh_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    float min_val,
    float max_val
);

torch::Tensor fused_spatial_mean_tanh_cuda(
    torch::Tensor input
);
"""

# Build the fused ops
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_header,
    cuda_sources=fused_ops_source,
    extra_cflags=["-O2"],
    extra_cuda_cflags=["-O2"],
    functions=[
        "fused_maxpool_hardtanh_cuda",
        "fused_spatial_mean_tanh_cuda"
    ],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a transposed convolution using PyTorch,
    then fused custom CUDA kernels for maxpool + hardtanh, and mean + tanh.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding,
                 maxpool_kernel_size, maxpool_stride, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels,
                                                 kernel_size=kernel_size,
                                                 stride=stride,
                                                 padding=padding)
        self.maxpool_kernel_size = maxpool_kernel_size
        self.maxpool_stride = maxpool_stride
        self.hardtanh_min = hardtanh_min
        self.hardtanh_max = hardtanh_max

    def forward(self, x):
        # Use standard nn.ConvTranspose2d
        x = self.conv_transpose(x)

        # Fused MaxPool + HardTanh
        x = fused_ops.fused_maxpool_hardtanh_cuda(
            x,
            self.maxpool_kernel_size,
            self.maxpool_stride,
            self.hardtanh_min,
            self.hardtanh_max
        )

        # Fused mean over spatial + tanh
        x = fused_ops.fused_spatial_mean_tanh_cuda(x)
        return x
